@media(max-width:760px){.source-content{overflow-x:hidden;min-width:0}.hero-copy{width:auto;right:5.4%}.hero h1{font-size:clamp(30px,10vw,44px)}.rail-head{flex-wrap:wrap;gap:6px}.filmrow{overflow-x:auto;padding-bottom:10px;scrollbar-width:none}.filmrow::-webkit-scrollbar{display:none}.rail-more{display:none}}</style>
